def get_icon_svg(name: str, color: str = "#3B82F6", size: int = 18) -> str:
    """Return rendered SVG string for named icon."""
    tmpl = ICONS.get(name, ICONS["shield"])
    return tmpl.format(color=color, size=size)


def card_metric_html(title: str, value: str, subtitle: str, icon_name: str, accent_color: str = "#3B82F6") -> str:
    """Render high-finish card metric with SVG icon."""
    icon_svg = get_icon_svg(icon_name, color=accent_color, size=22)
    return f"""
    <div style="background: #111827; border: 1px solid #1F2937; border-top: 3px solid {accent_color}; border-radius: 8px; padding: 16px 20px; margin-bottom: 12px; box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.1);">
        <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 8px;">
            <span style="color: #94A3B8; font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.5px;">{title}</span>
            <div style="background: rgba(15, 23, 42, 0.8); border: 1px solid #334155; border-radius: 6px; padding: 6px; display: flex; align-items: center; justify-content: center;">
                {icon_svg}
            </div>
        </div>
        <div style="color: #F8FAFC; font-size: 26px; font-weight: 700; letter-spacing: -0.5px; line-height: 1.2;">{value}</div>
        <div style="color: #64748B; font-size: 12px; font-weight: 500; margin-top: 6px;">{subtitle}</div>
    </div>
    """


def section_header_html(title: str, subtitle: str, icon_name: str, icon_color: str = "#3B82F6") -> str:
    """Render clean section title with inline vector icon."""
    icon_svg = get_icon_svg(icon_name, color=icon_color, size=20)
    return f"""
    <div style="display: flex; align-items: center; gap: 10px; margin-top: 20px; margin-bottom: 4px;">
        {icon_svg}
        <span style="color: #F8FAFC; font-size: 18px; font-weight: 700; letter-spacing: -0.3px;">{title}</span>
    </div>
    <div style="color: #94A3B8; font-size: 13px; margin-bottom: 14px; margin-left: 30px;">{subtitle}</div>
    """
